class User {}
class Admin: User {
    var permissions: [String] = ["read", "write"]
}
func countAdminPermissions(user: User) -> Int {
    if let admin = user as? Admin {
        return admin.permissions.count
    }
    return 0
}
let a = Admin()
let u = User()
print(countAdminPermissions(user: a))
print(countAdminPermissions(user: u))

