questions.modelAnswer:
func parseIntegerItem(_ item: Any) -> Int {
    if let number = item as? Int {
        return number * 2
    } else if let text = item as? String, let converted = Int(text) {
        return converted * 2
    }
    return -1
}
print(parseIntegerItem(21))
print(parseIntegerItem("15"))
print(parseIntegerItem(3.14))

