questions.modelAnswer:
class Media {}
class Book: Media { var pages = 300 }
class Song: Media { var duration = 180 }
func countBooks(in items: [Media]) -> Int {
    var count = 0
    for item in items {
        if item is Book {
            count += 1
        }
    } 
    return count
}
let collection: [Media] = [Book(), Song(), Book()]
print(countBooks(in: collection))
